import sqlite3,difflib
S="$S"
a=sqlite3.connect(f'file:{S}/pre135.db?mode=ro',uri=True); b=sqlite3.connect(f'file:{S}/post136.db?mode=ro',uri=True)
print(a.execute('pragma user_version').fetchone(), b.execute('pragma user_version').fetchone())
ma={(t,n):s for t,n,s in a.execute('select type,name,sql from sqlite_master')}
mb={(t,n):s for t,n,s in b.execute('select type,name,sql from sqlite_master')}
print('objects',len(ma),len(mb),'only a',set(ma)-set(mb),'only b',set(mb)-set(ma))
for k in ma:
    if k in mb and ma[k]!=mb[k]:
        print('DIFF',k)
        for l in difflib.unified_diff((ma[k] or '').splitlines(),(mb[k] or '').splitlines(),lineterm='',n=0): print('   ',l)
for t in ('source_value_extractions','extraction_lens_links'):
    ra=a.execute(f'select * from {t} order by 1').fetchall(); rb=b.execute(f'select * from {t} order by 1').fetchall()
    ca=[c[1:] for c in a.execute(f'pragma table_info({t})')]; cb=[c[1:] for c in b.execute(f'pragma table_info({t})')]
    print(t,len(ra),len(rb),ra==rb,'cols same',ca==cb, len(ca))
print(a.execute('select * from sqlite_sequence order by 1').fetchall()==b.execute('select * from sqlite_sequence order by 1').fetchall())
# all tables row compare
for (t,) in a.execute("select name from sqlite_master where type='table' and name not like 'sqlite_%'"):
    try:
        if a.execute(f'select * from "{t}" order by 1').fetchall()!=b.execute(f'select * from "{t}" order by 1').fetchall(): print('ROWS DIFFER',t)
    except Exception as e: print('ERR',t,e)
print(b.execute('pragma foreign_key_check').fetchall()[:5], b.execute('pragma integrity_check').fetchall())
# order of sqlite_master
oa=[n for n, in a.execute("select name from sqlite_master where type='view' order by rowid")]; ob=[n for n, in b.execute("select name from sqlite_master where type='view' order by rowid")]
print('view order same',oa==ob)
# FK lists of other tables referencing
for (t,) in b.execute("select name from sqlite_master where type='table'"):
    fa=a.execute(f'pragma foreign_key_list("{t}")').fetchall(); fb=b.execute(f'pragma foreign_key_list("{t}")').fetchall()
    if fa!=fb: print('FK differ',t)
print('triggers',a.execute("select count(*) from sqlite_master where type='trigger'").fetchone())
PY

